public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int i = 26; // 'z' has a value of 26

    while (n > 0 && k > 0) {
        if (k >= i) {
            k -= i;
            result.append((char) ('a' + i - 1));
            i--;
        } else {
            result.append('a');
            k--;
            // Reducing n might not affect the lexicographically smallest string
            n--;
        }
    }

    // If the last character was 'a', it means we need to decrease n
    if (result.length() > 0 && result.charAt(result.length() - 1) == 'a') {
        if (n > 0) {
            result.append('a');
            n--;
        }
    }

    // Reverse the string to get the lexicographically smallest order
    return new String(result.reverse().toString());
}

