public static int findSmallestInteger(int n) {
    // Convert the integer to a list of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int index = -1;

    // Find the first digit that can be swapped to form a smaller number
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            index = i;
            break;
        }
    }

    if (index == -1) {
        // If no such digit is found, no smaller rearrangement is possible
        return -1;
    }

    // Find the smallest digit in the remaining part of the array that is greater than digits[index]
    int minSwappableDigit = -1;
    for (int i = digits.length - 1; i > index; i--) {
        if (digits[i] > digits[index] && (minSwappableDigit == -1 || digits[i] < digits[minSwappableDigit])) {
            minSwappableDigit = i;
        }
    }

    // Swap the found digits
    char temp = digits[index];
    digits[index] = digits[minSwappableDigit];
    digits[minSwappableDigit] = temp;

    // Sort the remaining part of the array
    Arrays.sort(digits, index + 1, digits.length);

    // Convert the modified array back to an integer
    return Integer.parseInt(new String(digits));
}

